export type ParsedFulfillWithdrawalInstruction<
  TProgram extends string = typeof GAMMA_VAULT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Keeper signer. Must be the vault's fund_authority or keeper_authority. */
    signer: TAccountMetas[0];
    user: TAccountMetas[1];
    /** LpVault. */
    lpVault: TAccountMetas[2];
    /** Withdrawal policy used to retain the configured base-asset fee. */
    withdrawalPolicy: TAccountMetas[3];
    /** Vault's asset token account. */
    assetsAccount: TAccountMetas[4];
    /** Mint of the vault assets. */
    assetsMint: TAccountMetas[5];
    /** Mint for vault shares. */
    sharesMint: TAccountMetas[6];
    /** User's withdraw escrow. */
    withdrawEscrow: TAccountMetas[7];
    /** Escrow's asset token account (destination for assets). */
    escrowAssetsAccount: TAccountMetas[8];
    /** User's withdraw receipt. */
    withdrawReceipt: TAccountMetas[9];
    /** Token program. */
    tokenProgram: TAccountMetas[10];
  };
  data: FulfillWithdrawalInstructionData;
};

export function parseFulfillWithdrawalInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedFulfillWithdrawalInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 11,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      signer: getNextAccount(),
      user: getNextAccount(),
      lpVault: getNextAccount(),
      withdrawalPolicy: getNextAccount(),
      assetsAccount: getNextAccount(),
      assetsMint: getNextAccount(),
      sharesMint: getNextAccount(),
      withdrawEscrow: getNextAccount(),
      escrowAssetsAccount: getNextAccount(),
      withdrawReceipt: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getFulfillWithdrawalInstructionDataDecoder().decode(instruction.data),
  };
}
